      if(/^vault:/i.test(url)&&url.length>6){const id=url.slice(6);if(id.startsWith('SHR-'))return stash('<span class="wiki-link">'+label+'（共享引用，请使用本轮读取回执打开）</span>');return stash('<button class="wiki-link" data-open="'+id+'">'+label+'</button>');}
