    const caps=state.options?.capabilities,deepseek=model?.service_id==='deepseek';$('capabilities-detail').textContent=caps?['本轮服务：'+serviceLabel(model)+(model?.api_model?' · '+model.api_model:''),'附件：'+(caps.attachments?.enabled?'文本附件已接入；'+(deepseek?(list(model.input_modalities).includes('image')?'所选模型提供图片输入':'所选模型未提供图片输入'):'上传后由本轮使用'):'尚未接入'),'联网：'+(deepseek?(model.web_search?'所选 DeepSeek 模型提供内置搜索，额外 API 计费':'所选 DeepSeek 模型未提供内置搜索'):(caps.web_search?'已接入':'未提供')),'本机工具：'+(caps.native_tools?'已接入。可读取本机可访问文件，不限于已登记的个人资料；默认仅工作目录可写。普通命令与目录内写入不一定逐次审批，越界操作或连接器按请求审批。':'未提供'),'语音：'+({'native':'此窗口提供 macOS 听写桥接','browser':'此浏览器提供语音识别','unavailable':'此窗口未提供语音接口，可使用系统听写'})[workspaceSpeechMode(window)],model?.notice||'','这表示工作台接入能力，不代表所有桌面插件或 MCP 工具均可用。'].filter(Boolean).join('\n'):'尚未读取执行能力状态';
