  function setupDivider(id,property,min,max,reverse){const bar=$(id);let start=0,initial=0;const clamp=v=>Math.max(min,Math.min(max,v));bar.addEventListener('pointerdown',event=>{if(innerWidth<=900&&id==='left-divider')return;start=event.clientX;initial=parseFloat(getComputedStyle(document.documentElement).getPropertyValue(property));bar.setPointerCapture(event.pointerId);bar.classList.add('dragging');document.body.style.userSelect='none';});bar.addEventListener('pointermove',event=>{if(!bar.classList.contains('dragging'))return;const value=clamp(initial+(event.clientX-start)*(reverse?-1:1));document.documentElement.style.setProperty(property,value+'px');if($('output-dialog').open){syncOutputPresentation();if(outputState.modal)stop();}});const stop=()=>{bar.classList.remove('dragging');document.body.style.userSelect='';};bar.addEventListener('pointerup',stop);bar.addEventListener('pointercancel',stop);bar.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const current=parseFloat(getComputedStyle(document.documentElement).getPropertyValue(property)),delta=(event.key==='ArrowRight'?15:-15)*(reverse?-1:1);document.documentElement.style.setProperty(property,clamp(current+delta)+'px');if($('output-dialog').open)syncOutputPresentation();});}
