  function evidenceReferenceButton(ref){if(ref.kind==='growth_plan')return '<button class="evidence-source" data-plan-view="'+(ref.section==='panorama'?'panorama':'daily')+'">个人方案 · JSON</button>';if(ref.kind==='shared'||String(ref.id||'').startsWith('SHR-'))return '<button class="evidence-source shared-source" data-shared-open="'+escape(ref.id)+'" data-share-version="'+Number(ref.version)+'" data-shared-scope="'+escape(JSON.stringify(ref.shared_scope))+'" title="'+escape(ref.line_reference||'共享来源说明未记录')+'">'+escape(ref.title||'共享片段')+'<small class="shared-source-note">'+escape(ref.line_reference||'共享来源说明未记录')+'</small></button>';const id=ref.id||ref.file_id||ref.source_id||ref.skill_id,title=ref.title||ref.path||'资料';return id?'<button class="evidence-source" data-open="'+escape(id)+'" data-line="'+Math.max(1,Number(ref.line)||1)+'" title="'+escape(ref.path||title)+'">'+escape(title)+'</button>':'<span class="evidence-source">'+escape(title)+'</span>';}
  function currentEvidence(data){const context=data.reply_context||data.answer_context||data,advisors=list(data.advisor_selection||context.advisor_selection).filter(a=>a&&(a.title||a.name)&&(!a.status||a.status==='selected')),seen=new Set(),references=[...list(data.references||context.references),...list(data.advisor_reads||context.advisor_reads).map(a=>({...a,id:a.skill_id}))].filter(ref=>{if(!ref)return false;const key=[ref.id||ref.file_id||ref.source_id||ref.skill_id||ref.path||ref.title,ref.sha||''].join('|');if(seen.has(key))return false;seen.add(key);return true;});return {context,advisors,references,searches:list(data.knowledge_searches||context.knowledge_searches)};}
  function compactEvidenceHTML(data,{live=false}={}){
    const {context,advisors,references,searches}=currentEvidence(data);let html='<section class="turn-evidence" aria-label="本轮顾问与读取依据"><div class="evidence-line evidence-advisors">'+(advisors.length?'本轮顾问 · '+advisors.map(a=>escape(a.title||a.name)).join('、'):live?'顾问 · 尚未选用':'本轮无顾问选用回执')+'</div>';
    if(advisors.some(a=>a.reason))html+='<details class="evidence-reasons"><summary>查看选用理由</summary>'+advisors.filter(a=>a.reason).map(a=>'<p><strong>'+escape(a.title||a.name)+'</strong> · '+escape(a.reason)+'</p>').join('')+'</details>';
    html+='<div class="evidence-line evidence-reads"><span class="evidence-caption">'+(references.length?'本轮读取 · '+references.length+' 份':live?'资料 · 尚未读取':'无本轮读取回执')+'</span>'+references.slice(0,3).map(evidenceReferenceButton).join('')+'</div>';
    if(references.length>3)html+='<details class="evidence-more"><summary>更多已读资料 · '+(references.length-3)+'</summary><div class="evidence-reads">'+references.slice(3).map(evidenceReferenceButton).join('')+'</div></details>';
    if(searches.length)html+='<details class="evidence-searches"><summary>本轮搜索 · '+searches.length+' 次（搜索不等于读取）</summary>'+searches.map(search=>'<p>'+escape(search.query||'未记录查询词')+' · '+(Number.isFinite(search.count)?Math.max(0,search.count)+' 条结果':'结果数未记录')+(search.at?' · '+escape(search.at):'')+'</p>').join('')+'</details>';
    const previous=data.previous_evidence||context.previous_evidence;if(previous&&(list(previous.advisors).length||list(previous.references).length))html+='<details class="evidence-history"><summary>历史参考记录（不代表本轮使用）</summary>'+(list(previous.advisors).length?'<p>历史顾问 · '+previous.advisors.map(a=>escape(a.title||a.name||a)).join('、')+'</p>':'')+'<div class="evidence-reads">'+list(previous.references).map(evidenceReferenceButton).join('')+'</div>'+((previous.source_job_id||previous.recorded_at)?'<p>来源轮次：'+escape(previous.source_job_id||'未记录')+(previous.recorded_at?' · '+escape(previous.recorded_at):'')+'</p>':'')+'</details>';
    const snapshots=list(data.provided_context||context.provided_context);for(const group of [{status:'prepared',label:'准备附带概况',note:'概况已准备，尚未确认交给模型；不等同于本轮原文读取。'},{status:'provided',label:'已提供概况',note:'自动提供的概况，不等同于本轮原文读取。'},{status:'unknown',label:'概况交付状态待核实',note:'尚无确认交给模型的回执；不等同于本轮原文读取。'}]){const items=snapshots.filter(item=>group.status==='unknown'?!['prepared','provided'].includes(item.status):item.status===group.status);if(items.length)html+='<details class="evidence-provided"><summary>'+group.label+' · '+items.length+' 项</summary><p>'+group.note+'</p>'+items.map(item=>'<p>'+escape(item.title||'概况')+'</p>').join('')+'</details>';}
    const content=referenceHTML(data,{includeReceipts:false});if(content)html+='<details class="reply-evidence"><summary>详细回执与执行记录</summary>'+content+'</details>';return html+'</section>'+writeReceiptsHTML(data)+generatedOutputsHTML(data);
  }
